-- Run once in Supabase SQL Editor. No paid service is required.
create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users on delete cascade, username text not null unique check(char_length(username) between 2 and 32), bio text not null default '' check(char_length(bio)<=280), country text not null default '' check(country='' or country ~ '^[A-Z]{2}$'), avatar text not null default '' check(char_length(avatar)<150000), rating int not null default 1200, wins int not null default 0, losses int not null default 0, draws int not null default 0, banned boolean not null default false, created_at timestamptz not null default now());
create unique index profiles_username_ci on public.profiles(lower(username));
create function public.new_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into profiles(id,username) values(new.id,'player_'||substr(replace(new.id::text,'-',''),1,16));return new;end $$;
create trigger create_profile after insert on auth.users for each row execute function public.new_profile();
create table public.rooms(id uuid primary key default gen_random_uuid(),host uuid not null references profiles(id),name text not null check(char_length(name) between 1 and 80),mode text not null check(mode in('standard','throne','vote','team')),variant text not null default 'chess' check(variant in('chess','dropping','chaos','random')),state jsonb not null, members jsonb not null default '[]',queue jsonb not null default '[]',settings jsonb not null default '{}',revision int not null default 0,deadline timestamptz,status text not null default 'waiting',marks jsonb not null default '[]',last_rated_game text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.votes(id bigint generated always as identity primary key,room_id uuid not null references rooms on delete cascade,revision int not null,user_id uuid not null references profiles(id),move text not null,next_state jsonb not null,created_at timestamptz not null default now(),unique(room_id,revision,user_id));
create table public.messages(id bigint generated always as identity primary key,user_id uuid not null references profiles(id),body text not null check(char_length(body) between 1 and 600),created_at timestamptz not null default now());
create index messages_recent on public.messages(created_at desc);
create index votes_turn on public.votes(room_id,revision,created_at);
create table public.reports(id bigint generated always as identity primary key,reporter uuid not null references profiles(id),message_id bigint not null references messages on delete cascade,created_at timestamptz not null default now(),unique(reporter,message_id));
create table public.rated_games(room_id uuid not null,game_key text not null,white uuid not null references profiles(id),black uuid not null references profiles(id),result text not null,created_at timestamptz not null default now(),primary key(room_id,game_key));
alter table profiles enable row level security;alter table rooms enable row level security;alter table votes enable row level security;alter table messages enable row level security;alter table reports enable row level security;alter table rated_games enable row level security;
create policy profile_read on profiles for select using(true);
create policy profile_edit on profiles for update to authenticated using(auth.uid()=id) with check(auth.uid()=id);
revoke update on public.profiles from authenticated;grant update(username,bio,country,avatar) on public.profiles to authenticated;
create policy room_read on rooms for select to authenticated using(true);
create policy vote_read on votes for select to authenticated using(true);
create policy message_read on messages for select to authenticated using(true);
create policy message_delete on messages for delete to authenticated using(user_id=auth.uid());
create policy report_insert on reports for insert to authenticated with check(reporter=auth.uid());
create policy rated_read on rated_games for select using(true);
-- Only verified Edge Function requests can change games, votes or ratings.
create function public.commit_room(p_id uuid,p_revision int,p_state jsonb,p_members jsonb,p_queue jsonb,p_status text,p_deadline timestamptz,p_marks jsonb) returns public.rooms language plpgsql security definer set search_path=public as $$ declare r rooms;begin update rooms set state=p_state,members=p_members,queue=p_queue,status=p_status,deadline=p_deadline,marks=p_marks,revision=revision+1,updated_at=now() where id=p_id and revision=p_revision returning * into r;if r.id is null then raise exception 'Position changed. Refresh and try again.';end if;return r;end $$;
revoke all on function public.commit_room(uuid,int,jsonb,jsonb,jsonb,text,timestamptz,jsonb) from public,anon,authenticated;grant execute on function public.commit_room(uuid,int,jsonb,jsonb,jsonb,text,timestamptz,jsonb) to service_role;
create function public.cast_vote(p_room uuid,p_revision int,p_user uuid,p_move text,p_state jsonb) returns void language plpgsql security definer set search_path=public as $$ declare r rooms;begin select * into r from rooms where id=p_room for update;if jsonb_array_length(r.state->'moves')<>p_revision or r.mode<>'vote' or r.deadline<=now() then raise exception 'Voting period has closed.';end if;insert into votes(room_id,revision,user_id,move,next_state) values(p_room,p_revision,p_user,p_move,p_state) on conflict(room_id,revision,user_id) do update set move=excluded.move,next_state=excluded.next_state,created_at=case when votes.move=excluded.move then votes.created_at else now() end;end $$;
revoke all on function public.cast_vote(uuid,int,uuid,text,jsonb) from public,anon,authenticated;grant execute on function public.cast_vote(uuid,int,uuid,text,jsonb) to service_role;
create function public.post_message(p_body text) returns void language plpgsql security definer set search_path=public as $$ declare n int;begin if auth.uid() is null or exists(select 1 from profiles where id=auth.uid() and banned)then raise exception 'Sign in to chat.';end if;perform 1 from profiles where id=auth.uid() for update;select count(*) into n from messages where user_id=auth.uid() and created_at>now()-interval '10 seconds';if n>=4 then raise exception 'Please wait before sending another message.';end if;insert into messages(user_id,body) values(auth.uid(),trim(p_body));end $$;
revoke all on function public.post_message(text) from public,anon;grant execute on function public.post_message(text) to authenticated;
-- Finalize due votes inside Postgres: exactly 24h, majority wins, earliest ballot breaks a tie.
create function public.close_due_votes() returns void language plpgsql security definer set search_path=public as $$ declare r rooms;v record;begin for r in select * from rooms where mode='vote' and status='playing' and deadline<=now() for update skip locked loop select move,min(id) as first_id,count(*) as total into v from votes where room_id=r.id and revision=jsonb_array_length(r.state->'moves') group by move order by count(*) desc,min(created_at),min(id) limit 1;if v.move is not null then update rooms set state=(select next_state from votes where id=v.first_id),revision=revision+1,marks='[]',status=case when (select next_state->>'result' from votes where id=v.first_id)='*' then 'playing' else 'finished' end,deadline=r.deadline+interval '1 day',updated_at=now() where id=r.id;else update rooms set deadline=now()+interval '1 day',updated_at=now() where id=r.id;end if;end loop;end $$;
revoke all on function public.close_due_votes() from public,anon,authenticated;grant execute on function public.close_due_votes() to service_role;
create function public.rate_game(p_room uuid,p_key text,p_white uuid,p_black uuid,p_result text) returns void language plpgsql security definer set search_path=public as $$ declare wr int;br int;delta int;begin if p_white=p_black or p_result not in('1-0','0-1','1/2-1/2')then return;end if;perform 1 from profiles where id in(p_white,p_black) order by id for update;insert into rated_games(room_id,game_key,white,black,result) values(p_room,p_key,p_white,p_black,p_result) on conflict do nothing;if not found then return;end if;select rating into wr from profiles where id=p_white;select rating into br from profiles where id=p_black;delta=round(24*((case p_result when '1-0' then 1 when '0-1' then 0 else .5 end)-1/(1+power(10.0,(br-wr)/400.0))));update profiles set rating=greatest(100,rating+delta),wins=wins+(p_result='1-0')::int,losses=losses+(p_result='0-1')::int,draws=draws+(p_result='1/2-1/2')::int where id=p_white;update profiles set rating=greatest(100,rating-delta),wins=wins+(p_result='0-1')::int,losses=losses+(p_result='1-0')::int,draws=draws+(p_result='1/2-1/2')::int where id=p_black;end $$;
revoke all on function public.rate_game(uuid,text,uuid,uuid,text) from public,anon,authenticated;grant execute on function public.rate_game(uuid,text,uuid,uuid,text) to service_role;
create view public.rankings with(security_invoker=true) as select id,username,country,avatar,rating,wins,losses,draws,rank()over(order by rating desc)as global_rank,rank()over(partition by country order by rating desc)as country_rank,round(100.0*(1-percent_rank()over(order by rating desc))::numeric,1)as global_percentile,round(100.0*(1-percent_rank()over(partition by country order by rating desc))::numeric,1)as country_percentile from profiles where wins+losses+draws>=5 and not banned;
alter publication supabase_realtime add table public.rooms,public.messages,public.votes;
-- In Database > Extensions, enable pg_cron, then run the following statement.
-- select cron.schedule('novachess-votes','* * * * *','select public.close_due_votes()');
-- Optional retention: delete messages older than 90 days with a separate daily cron job.

grant select on public.profiles,public.rankings,public.rated_games to anon,authenticated;
grant select on public.rooms,public.votes,public.messages to authenticated;
grant delete on public.messages to authenticated;
grant insert on public.reports to authenticated;
grant usage on sequence public.reports_id_seq to authenticated;
